namespace Astronomy.MediaFactory.Core.DocumentaryBlueprint;

public sealed class DocumentaryExportSpecificationPolicy
{
    public DocumentaryExportSpecificationPolicy(bool requireCertifiedRecord,bool requireCompleteProductionPackage,bool requireCompleteProvenance,bool requireCanonicalItems,bool requireCanonicalOrdering,bool requireExactCorrelation,bool requireDeterministicIdentity,bool requireDeterministicDependencies,IReadOnlyList<DocumentaryExportItemType> requiredItemTypes,IReadOnlyList<DocumentaryExportContentType> requiredContentTypes,DocumentaryExportEncoding exportEncoding,string policySchemaVersion)
    { if(new[]{requireCertifiedRecord,requireCompleteProductionPackage,requireCompleteProvenance,requireCanonicalItems,requireCanonicalOrdering,requireExactCorrelation,requireDeterministicIdentity,requireDeterministicDependencies}.Any(x=>!x))throw new ArgumentException("Every schema 1.0 control is required.");if(requiredItemTypes is null||!requiredItemTypes.SequenceEqual(DocumentaryExportSpecificationInventory.Items))throw new ArgumentException("Item inventory must be canonical.",nameof(requiredItemTypes));if(requiredContentTypes is null||!requiredContentTypes.SequenceEqual(DocumentaryExportSpecificationInventory.Contents))throw new ArgumentException("Content inventory must be canonical.",nameof(requiredContentTypes));if(exportEncoding!=DocumentaryExportEncoding.StructuredJson)throw new ArgumentException("Encoding must be StructuredJson.",nameof(exportEncoding));PolicySchemaVersion=policySchemaVersion=="1.0"?policySchemaVersion:throw new ArgumentException("Schema must be 1.0.",nameof(policySchemaVersion));RequireCertifiedRecord=requireCertifiedRecord;RequireCompleteProductionPackage=requireCompleteProductionPackage;RequireCompleteProvenance=requireCompleteProvenance;RequireCanonicalItems=requireCanonicalItems;RequireCanonicalOrdering=requireCanonicalOrdering;RequireExactCorrelation=requireExactCorrelation;RequireDeterministicIdentity=requireDeterministicIdentity;RequireDeterministicDependencies=requireDeterministicDependencies;RequiredItemTypes=DocumentaryExportSpecificationInventory.Copy(requiredItemTypes,nameof(requiredItemTypes));RequiredContentTypes=DocumentaryExportSpecificationInventory.Copy(requiredContentTypes,nameof(requiredContentTypes));ExportEncoding=exportEncoding; }
    public bool RequireCertifiedRecord{get;} public bool RequireCompleteProductionPackage{get;} public bool RequireCompleteProvenance{get;} public bool RequireCanonicalItems{get;} public bool RequireCanonicalOrdering{get;} public bool RequireExactCorrelation{get;} public bool RequireDeterministicIdentity{get;} public bool RequireDeterministicDependencies{get;} public IReadOnlyList<DocumentaryExportItemType> RequiredItemTypes{get;} public IReadOnlyList<DocumentaryExportContentType> RequiredContentTypes{get;} public DocumentaryExportEncoding ExportEncoding{get;} public string PolicySchemaVersion{get;}
}
public sealed class DocumentaryExportSpecificationMetadata
{ public DocumentaryExportSpecificationMetadata(DateTimeOffset createdUtc,string createdBy,string exportSchemaVersion,string correlationId){CreatedUtc=createdUtc!=default?createdUtc:throw new ArgumentException("Timestamp is required.",nameof(createdUtc));CreatedBy=Guard.Required(createdBy,nameof(createdBy));ExportSchemaVersion=exportSchemaVersion=="1.0"?exportSchemaVersion:throw new ArgumentException("Schema must be 1.0.",nameof(exportSchemaVersion));CorrelationId=Guard.Required(correlationId,nameof(correlationId));} public DateTimeOffset CreatedUtc{get;} public string CreatedBy{get;} public string ExportSchemaVersion{get;} public string CorrelationId{get;} }
public sealed class DocumentaryExportSpecificationRequest
{ public DocumentaryExportSpecificationRequest(DocumentaryCertificationRecord certificationRecord,DocumentaryExportSpecificationPolicy policy,DocumentaryExportSpecificationMetadata metadata,DocumentaryExportProfile profile){CertificationRecord=certificationRecord??throw new ArgumentNullException(nameof(certificationRecord));Policy=policy??throw new ArgumentNullException(nameof(policy));Metadata=metadata??throw new ArgumentNullException(nameof(metadata));Guard.Enum(profile,nameof(profile));Profile=profile;} public DocumentaryCertificationRecord CertificationRecord{get;} public DocumentaryExportSpecificationPolicy Policy{get;} public DocumentaryExportSpecificationMetadata Metadata{get;} public DocumentaryExportProfile Profile{get;} }
public sealed class DocumentaryExportItemDependency
{ public DocumentaryExportItemDependency(string dependencyId,DocumentaryExportItemType sourceItemType,DocumentaryExportItemType targetItemType,int sequence,string correlationId){DependencyId=Guard.Required(dependencyId,nameof(dependencyId));Guard.Enum(sourceItemType,nameof(sourceItemType));Guard.Enum(targetItemType,nameof(targetItemType));if(sourceItemType==targetItemType)throw new ArgumentException("Dependency endpoints must differ.");if(dependencyId!=$"{sourceItemType}.depends-on.{targetItemType}")throw new ArgumentException("Dependency identity is inconsistent.",nameof(dependencyId));if(sequence<0)throw new ArgumentOutOfRangeException(nameof(sequence));CorrelationId=Guard.Required(correlationId,nameof(correlationId));SourceItemType=sourceItemType;TargetItemType=targetItemType;Sequence=sequence;} public string DependencyId{get;} public DocumentaryExportItemType SourceItemType{get;} public DocumentaryExportItemType TargetItemType{get;} public int Sequence{get;} public string CorrelationId{get;} }
public sealed class DocumentaryExportSpecificationItem
{ public DocumentaryExportSpecificationItem(string itemId,DocumentaryExportItemType itemType,DocumentaryExportItemRequirement requirement,DocumentaryExportContentType contentType,DocumentaryExportEncoding encoding,string artifactIdentity,string artifactVersion,int sequence,IReadOnlyList<DocumentaryExportItemDependency> dependencies,string correlationId){ItemId=Guard.Required(itemId,nameof(itemId));Guard.Enum(itemType,nameof(itemType));Guard.Enum(requirement,nameof(requirement));Guard.Enum(contentType,nameof(contentType));Guard.Enum(encoding,nameof(encoding));ArtifactIdentity=Guard.Required(artifactIdentity,nameof(artifactIdentity));ArtifactVersion=Guard.Required(artifactVersion,nameof(artifactVersion));if(itemId!=$"{itemType}.{artifactIdentity}.{artifactVersion}")throw new ArgumentException("Item identity is inconsistent.",nameof(itemId));if(sequence<0)throw new ArgumentOutOfRangeException(nameof(sequence));var copy=DocumentaryExportSpecificationInventory.Copy(dependencies,nameof(dependencies));if(copy.Any(x=>x.SourceItemType!=itemType)||copy.Select(x=>x.DependencyId).Distinct(StringComparer.Ordinal).Count()!=copy.Count||!copy.Select(x=>x.Sequence).SequenceEqual(Enumerable.Range(0,copy.Count)))throw new ArgumentException("Dependencies must be unique, contiguous, and sourced by this item.",nameof(dependencies));CorrelationId=Guard.Required(correlationId,nameof(correlationId));ItemType=itemType;Requirement=requirement;ContentType=contentType;Encoding=encoding;Sequence=sequence;Dependencies=copy;} public string ItemId{get;} public DocumentaryExportItemType ItemType{get;} public DocumentaryExportItemRequirement Requirement{get;} public DocumentaryExportContentType ContentType{get;} public DocumentaryExportEncoding Encoding{get;} public string ArtifactIdentity{get;} public string ArtifactVersion{get;} public int Sequence{get;} public IReadOnlyList<DocumentaryExportItemDependency> Dependencies{get;} public string CorrelationId{get;} }
public sealed class DocumentaryExportSpecificationManifest
{ public DocumentaryExportSpecificationManifest(string manifestId,string exportSpecificationId,DocumentaryExportProfile profile,IReadOnlyList<DocumentaryExportSpecificationItem> items,int itemCount,int requiredItemCount,DocumentaryExportEncoding encoding,string manifestSchemaVersion,string correlationId){ManifestId=Guard.Required(manifestId,nameof(manifestId));ExportSpecificationId=Guard.Required(exportSpecificationId,nameof(exportSpecificationId));Guard.Enum(profile,nameof(profile));if(manifestId!=$"{exportSpecificationId}.manifest")throw new ArgumentException("Manifest identity is inconsistent.");Items=DocumentaryExportSpecificationInventory.Copy(items,nameof(items));if(!DocumentaryExportSpecificationValidator.ItemsValid(Items,correlationId)||itemCount!=10||requiredItemCount!=10)throw new ArgumentException("Manifest inventory is inconsistent.");if(encoding!=DocumentaryExportEncoding.StructuredJson)throw new ArgumentException("Encoding is inconsistent.");ManifestSchemaVersion=manifestSchemaVersion=="1.0"?manifestSchemaVersion:throw new ArgumentException("Schema must be 1.0.");CorrelationId=Guard.Required(correlationId,nameof(correlationId));Profile=profile;ItemCount=itemCount;RequiredItemCount=requiredItemCount;Encoding=encoding;} public string ManifestId{get;} public string ExportSpecificationId{get;} public DocumentaryExportProfile Profile{get;} public IReadOnlyList<DocumentaryExportSpecificationItem> Items{get;} public int ItemCount{get;} public int RequiredItemCount{get;} public DocumentaryExportEncoding Encoding{get;} public string ManifestSchemaVersion{get;} public string CorrelationId{get;} }
public sealed class DocumentaryExportSpecification
{ public DocumentaryExportSpecification(string exportSpecificationId,DocumentaryCertificationRecord certificationRecord,DocumentaryProvenanceRecord provenanceRecord,DocumentaryProductionPackage productionPackage,DocumentaryExportProfile profile,DocumentaryExportSpecificationPolicy policy,DocumentaryExportSpecificationMetadata metadata,IReadOnlyList<DocumentaryExportSpecificationItem> items,DocumentaryExportSpecificationManifest manifest,string certificationId,string provenanceId,string packageId,string releaseCandidateId,string convergenceId,int itemCount,int requiredItemCount,bool isComplete){ExportSpecificationId=Guard.Required(exportSpecificationId,nameof(exportSpecificationId));CertificationRecord=certificationRecord??throw new ArgumentNullException(nameof(certificationRecord));ProvenanceRecord=provenanceRecord??throw new ArgumentNullException(nameof(provenanceRecord));ProductionPackage=productionPackage??throw new ArgumentNullException(nameof(productionPackage));Policy=policy??throw new ArgumentNullException(nameof(policy));Metadata=metadata??throw new ArgumentNullException(nameof(metadata));Manifest=manifest??throw new ArgumentNullException(nameof(manifest));Guard.Enum(profile,nameof(profile));Items=DocumentaryExportSpecificationInventory.Copy(items,nameof(items));CertificationId=Guard.Required(certificationId,nameof(certificationId));ProvenanceId=Guard.Required(provenanceId,nameof(provenanceId));PackageId=Guard.Required(packageId,nameof(packageId));ReleaseCandidateId=Guard.Required(releaseCandidateId,nameof(releaseCandidateId));ConvergenceId=Guard.Required(convergenceId,nameof(convergenceId));Profile=profile;ItemCount=itemCount;RequiredItemCount=requiredItemCount;if(!isComplete||!DocumentaryExportSpecificationValidator.SpecificationValid(this))throw new ArgumentException("Export specification is inconsistent.");IsComplete=true;} public string ExportSpecificationId{get;} public DocumentaryCertificationRecord CertificationRecord{get;} public DocumentaryProvenanceRecord ProvenanceRecord{get;} public DocumentaryProductionPackage ProductionPackage{get;} public DocumentaryExportProfile Profile{get;} public DocumentaryExportSpecificationPolicy Policy{get;} public DocumentaryExportSpecificationMetadata Metadata{get;} public IReadOnlyList<DocumentaryExportSpecificationItem> Items{get;} public DocumentaryExportSpecificationManifest Manifest{get;} public string CertificationId{get;} public string ProvenanceId{get;} public string PackageId{get;} public string ReleaseCandidateId{get;} public string ConvergenceId{get;} public int ItemCount{get;} public int RequiredItemCount{get;} public bool IsComplete{get;} }
public sealed class DocumentaryExportSpecificationBuildResult
{ public DocumentaryExportSpecificationBuildResult(DocumentaryExportSpecificationStatus status,IReadOnlyList<DocumentaryExportSpecificationRejectionReason> rejectionReasons,DocumentaryExportSpecification? exportSpecification){Guard.Enum(status,nameof(status));var copy=DocumentaryExportSpecificationInventory.Copy(rejectionReasons,nameof(rejectionReasons));if(copy.Any(x=>!Enum.IsDefined(x))||copy.Distinct().Count()!=copy.Count||!copy.SequenceEqual(copy.OrderBy(x=>(int)x)))throw new ArgumentException("Reasons must be defined, unique, and ordered.");if(status==DocumentaryExportSpecificationStatus.Complete?(copy.Count!=0||exportSpecification is null):(copy.Count==0||exportSpecification is not null))throw new ArgumentException("Build result is inconsistent.");Status=status;RejectionReasons=copy;ExportSpecification=exportSpecification;} public DocumentaryExportSpecificationStatus Status{get;} public IReadOnlyList<DocumentaryExportSpecificationRejectionReason> RejectionReasons{get;} public DocumentaryExportSpecification? ExportSpecification{get;} public bool HasExportSpecification=>ExportSpecification is not null; public bool IsComplete=>Status==DocumentaryExportSpecificationStatus.Complete; public bool IsRejected=>!IsComplete; }
public sealed class DocumentaryExportSpecificationSummary
{ public DocumentaryExportSpecificationSummary(string exportSpecificationId,string manifestId,string certificationId,string provenanceId,string packageId,string releaseCandidateId,string convergenceId,DocumentaryExportProfile profile,DocumentaryExportEncoding encoding,int itemCount,int requiredItemCount,int dependencyCount,IReadOnlyList<DocumentaryExportItemType> itemTypes,IReadOnlyList<DocumentaryExportContentType> contentTypes,DateTimeOffset createdUtc,string createdBy,bool isComplete){ExportSpecificationId=Guard.Required(exportSpecificationId,nameof(exportSpecificationId));ManifestId=Guard.Required(manifestId,nameof(manifestId));CertificationId=Guard.Required(certificationId,nameof(certificationId));ProvenanceId=Guard.Required(provenanceId,nameof(provenanceId));PackageId=Guard.Required(packageId,nameof(packageId));ReleaseCandidateId=Guard.Required(releaseCandidateId,nameof(releaseCandidateId));ConvergenceId=Guard.Required(convergenceId,nameof(convergenceId));if(profile!=DocumentaryExportProfile.CertifiedKnowledgePackage||encoding!=DocumentaryExportEncoding.StructuredJson||itemCount!=10||requiredItemCount!=10||dependencyCount!=23||itemTypes is null||!itemTypes.SequenceEqual(DocumentaryExportSpecificationInventory.Items)||contentTypes is null||!contentTypes.SequenceEqual(DocumentaryExportSpecificationInventory.Contents)||createdUtc==default||!isComplete)throw new ArgumentException("Summary is inconsistent.");CreatedBy=Guard.Required(createdBy,nameof(createdBy));Profile=profile;Encoding=encoding;ItemCount=itemCount;RequiredItemCount=requiredItemCount;DependencyCount=dependencyCount;ItemTypes=DocumentaryExportSpecificationInventory.Copy(itemTypes,nameof(itemTypes));ContentTypes=DocumentaryExportSpecificationInventory.Copy(contentTypes,nameof(contentTypes));CreatedUtc=createdUtc;IsComplete=true;} public string ExportSpecificationId{get;} public string ManifestId{get;} public string CertificationId{get;} public string ProvenanceId{get;} public string PackageId{get;} public string ReleaseCandidateId{get;} public string ConvergenceId{get;} public DocumentaryExportProfile Profile{get;} public DocumentaryExportEncoding Encoding{get;} public int ItemCount{get;} public int RequiredItemCount{get;} public int DependencyCount{get;} public IReadOnlyList<DocumentaryExportItemType> ItemTypes{get;} public IReadOnlyList<DocumentaryExportContentType> ContentTypes{get;} public DateTimeOffset CreatedUtc{get;} public string CreatedBy{get;} public bool IsComplete{get;} }
